using System;using System.Linq;using System.Collections;using UnityEngine;
[DefaultExecutionOrder(11080)]
[DisallowMultipleComponent]
public sealed class DrumSetSupplement : MonoBehaviour
{
 private DrumBellSequence sequence;private Transform[] tapes;private AudioSource source;private AudioClip strike;private Coroutine vibration;private Vector3 restPosition;private Quaternion restRotation;private bool vibrating;private Coroutine completion;
 private Renderer[] fadingRenderers;private Material[][] originalMaterials;private Material[] fadeMaterials;
 public float RevealProgress {get;private set;}
 public bool IsCompleting {get;private set;}public int RewardBellNumber {get;private set;}
 public int TapCount {get;private set;}public bool IsSolved {get;private set;}public bool IsDropping {get;private set;}public Transform DroppedTape {get;private set;}
 public void Configure(DrumBellSequence owner,Transform[] rewards){if(sequence)sequence.PatternChanged-=ResetCount;sequence=owner;tapes=rewards;sequence.PatternChanged+=ResetCount;if(!IsSolved&&tapes!=null)foreach(var tape in tapes){if(!tape)continue;foreach(var r in tape.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var c in tape.GetComponentsInChildren<Collider>(true))c.enabled=false;foreach(var h in tape.GetComponentsInChildren<HoverScanHighlight>(true))h.enabled=false;foreach(var pickup in tape.GetComponentsInChildren<AlloyPickup>(true))pickup.enabled=false;}if(!source){source=gameObject.AddComponent<AudioSource>();source.playOnAwake=false;source.spatialBlend=.65f;source.minDistance=35;source.maxDistance=400;source.pitch=1f;strike=Resources.Load<AudioClip>("DrumBells/DrumSetHit");}var mesh=GetComponent<MeshFilter>();if(!GetComponent<Collider>()&&mesh)gameObject.AddComponent<MeshCollider>().sharedMesh=mesh.sharedMesh;}
 private void ResetCount(){TapCount=0;}
 private void LateUpdate(){if(!Application.isFocused||EvidenceInspect.BlocksWorldInput||!Input.GetMouseButtonDown(0))return;var camera=Camera.main;if(camera)TryClick(camera,Cursor.lockState==CursorLockMode.Locked?camera.pixelRect.center:(Vector2)Input.mousePosition);}
 public bool TryClick(Camera camera,Vector2 pointer){if(!camera||!camera.pixelRect.Contains(pointer)||EvidenceInspect.BlocksWorldInput)return false;var hits=Physics.RaycastAll(camera.ScreenPointToRay(pointer),1000,~((1<<30)|(1<<31)),QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance);foreach(var h in hits){if(h.collider.GetComponentInParent<FirstPersonPlayer>())continue;if(h.transform!=transform&&!h.transform.IsChildOf(transform))return false;return Vector3.Distance(camera.transform.position,h.point)<=180&&Tap();}return false;}
 public bool Tap(){var inventory=FindObjectOfType<ImportantItemCollectionUI>();if(IsCompleting||!sequence||!inventory||!inventory.HasWood)return false;if(source&&strike)Scene2AudioPlayback.PlayOneShot(source,strike,.65f);StartVibration();if(IsSolved||sequence.HitCount==0)return true;TapCount++;if(TapCount==sequence.MissingBellNumber){if(tapes==null||tapes.Length!=4||tapes.Any(t=>!t)){Debug.LogWarning("Four cidai rewards are required for the reward.",this);return true;}IsSolved=true;RewardBellNumber=sequence.MissingBellNumber;DroppedTape=tapes[UnityEngine.Random.Range(0,tapes.Length)];completion=StartCoroutine(CompleteThenDrop());}return true;}
 private IEnumerator CompleteThenDrop(){IsCompleting=true;sequence.BeginCompletion();while(sequence&&sequence.Bells.Any(b=>b&&b.IsSwinging))yield return null;if(sequence)yield return Drop(DroppedTape,sequence.Bells[RewardBellNumber-1]);if(sequence)sequence.EndCompletion();IsCompleting=false;completion=null;}
 private void StartVibration(){if(vibration!=null){StopCoroutine(vibration);RestoreVibration();}restPosition=transform.position;restRotation=transform.rotation;vibration=StartCoroutine(Vibrate());}
 private IEnumerator Vibrate(){vibrating=true;for(float t=0;t<.28f;t+=Time.deltaTime){float wave=Mathf.Sin(t*2*Mathf.PI*23)*Mathf.Exp(-t*14);transform.position=restPosition+Vector3.up*(.28f*wave);transform.rotation=Quaternion.AngleAxis(.45f*wave,Vector3.forward)*restRotation;yield return null;}RestoreVibration();vibration=null;}
 private void RestoreVibration(){if(!vibrating)return;transform.SetPositionAndRotation(restPosition,restRotation);vibrating=false;}
 private IEnumerator Drop(Transform tape,BellMicroSwing originBell){IsDropping=true;RevealProgress=0;var originalScale=tape.localScale;var renderers=tape.GetComponentsInChildren<Renderer>(true);fadingRenderers=renderers;originalMaterials=renderers.Select(r=>r.sharedMaterials).ToArray();
 var shader=Resources.Load<Shader>("DrumBells/TapeRewardFade");var temporary=new System.Collections.Generic.List<Material>();
 for(int i=0;i<renderers.Length;i++){var copies=originalMaterials[i].Select(original=>{var copy=new Material(original);if(shader)copy.shader=shader;copy.SetFloat("_RevealAlpha",0);temporary.Add(copy);return copy;}).ToArray();renderers[i].sharedMaterials=copies;}
 fadeMaterials=temporary.ToArray();PlaceTape(tape,renderers,originBell.RestBounds,originalScale,0);foreach(var r in renderers)r.enabled=true;
 for(float time=0;time<.9f;time+=Time.deltaTime){float t=Mathf.Clamp01(time/.9f);float progress=Mathf.SmoothStep(0,1,t);RevealProgress=progress;PlaceTape(tape,renderers,originBell.RestBounds,originalScale,progress);foreach(var m in fadeMaterials)m.SetFloat("_RevealAlpha",progress);yield return null;}
 RevealProgress=1;PlaceTape(tape,renderers,originBell.RestBounds,originalScale,1);RestoreFadeMaterials();
 foreach(var c in tape.GetComponentsInChildren<Collider>(true))c.enabled=true;
 foreach(var f in tape.GetComponentsInChildren<MeshFilter>(true)){if(!f.sharedMesh||!f.GetComponent<Renderer>())continue;if(!f.GetComponent<Collider>())f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;var hover=f.GetComponent<HoverScanHighlight>();if(!hover)hover=f.gameObject.AddComponent<HoverScanHighlight>();hover.ConfigureScene2();hover.Configure(6,180);hover.enabled=true;var pickup=f.GetComponent<AlloyPickup>();if(!pickup)pickup=f.gameObject.AddComponent<AlloyPickup>();pickup.ConfigureTape(tape);pickup.enabled=true;}IsDropping=false;}
 private static void PlaceTape(Transform tape,Renderer[] renderers,Bounds bellBounds,Vector3 originalScale,float progress){tape.localScale=originalScale*Mathf.Lerp(1,3f,progress);var bounds=new Bounds(tape.position,Vector3.zero);if(renderers.Length>0){bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);}var offset=bounds.center-tape.position;float topOffset=bounds.max.y-tape.position.y;tape.position=new Vector3(bellBounds.center.x-offset.x,bellBounds.min.y-.4f-progress*5f-topOffset,bellBounds.center.z-offset.z);}
 private void RestoreFadeMaterials(){if(fadingRenderers!=null&&originalMaterials!=null)for(int i=0;i<fadingRenderers.Length;i++)if(fadingRenderers[i])fadingRenderers[i].sharedMaterials=originalMaterials[i];if(fadeMaterials!=null)foreach(var m in fadeMaterials)if(m)Destroy(m);fadingRenderers=null;originalMaterials=null;fadeMaterials=null;}
 private void OnDisable(){RestoreFadeMaterials();if(completion!=null){StopCoroutine(completion);completion=null;IsCompleting=false;IsDropping=false;if(sequence)sequence.EndCompletion();}if(vibration!=null)StopCoroutine(vibration);vibration=null;RestoreVibration();}
 private void OnDestroy(){RestoreFadeMaterials();RestoreVibration();if(sequence)sequence.PatternChanged-=ResetCount;}
}
